<?php
require_once __DIR__ . '/../includes/auth.php'; require __DIR__ . '/../includes/db.php';
$id=(int)($_GET['id']??0); if(!$id){header('Location: manage.php');exit;}
$stmt=$conn->prepare("SELECT r.*, c.full_name,c.phone_number,c.email,c.license_no,c.id_number,c.address, ca.reg_no,ca.vin,ca.color, m.name AS make_name, mo.name AS model_name, y.year AS car_year FROM rentals r JOIN customers c ON r.customer_id=c.id JOIN cars ca ON r.cars_id=ca.id LEFT JOIN makes m ON ca.make_id=m.id LEFT JOIN models mo ON ca.model_id=mo.id LEFT JOIN car_years y ON ca.year_id=y.id WHERE r.id=? LIMIT 1"); $stmt->bind_param('i',$id); $stmt->execute(); $r=$stmt->get_result()->fetch_assoc(); if(!$r){header('Location: manage.php');exit;}
?>
<!DOCTYPE html><html><head><title>Rental Agreement #<?=h($id)?></title><style>body{font-family:Arial;color:#111;padding:30px}.agreement{max-width:900px;margin:auto;border:2px solid #111;padding:28px}.header{text-align:center;border-bottom:1px solid #111;margin-bottom:20px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.box{border:1px solid #999;padding:12px;margin-bottom:14px}table{width:100%;border-collapse:collapse}td,th{border:1px solid #999;padding:8px}.sign{display:grid;grid-template-columns:1fr 1fr;gap:60px;margin-top:50px}.line{border-top:1px solid #111;padding-top:8px}@media print{button{display:none}body{padding:0}.agreement{border:0}}</style></head><body><button onclick="window.print()">Print Agreement</button><div class="agreement"><div class="header"><?php if(cr_setting('company_logo')!==''):?><img src="<?=h(app_url('settings/logo.php'))?>" alt="" style="max-height:70px;margin-bottom:8px"><?php endif;?><h2 style="margin:0"><?=h(cr_company_name())?></h2><p style="margin:4px 0;color:#444"><?=h(implode(' | ', array_filter([cr_setting('company_address'), cr_setting('company_phone'), cr_setting('company_email'), cr_setting('company_tax_id')!=='' ? 'Tax ID: '.cr_setting('company_tax_id') : ''])))?></p><h1>CAR RENTAL AGREEMENT</h1><p>Agreement No: CR-<?=h(str_pad((string)$id,5,'0',STR_PAD_LEFT))?> | Date: <?=h(cr_date(date('Y-m-d')))?></p></div><div class="grid"><div class="box"><h3>Customer</h3><p><strong>Name:</strong> <?=h($r['full_name'])?></p><p><strong>Phone:</strong> <?=h($r['phone_number'])?></p><p><strong>Email:</strong> <?=h($r['email'])?></p><p><strong>License:</strong> <?=h($r['license_no'])?></p><p><strong>ID/Passport:</strong> <?=h($r['id_number'])?></p><p><strong>Address:</strong> <?=h($r['address'])?></p></div><div class="box"><h3>Vehicle</h3><p><strong>Car:</strong> <?=h(car_display_name($r))?></p><p><strong>Registration:</strong> <?=h($r['reg_no'])?></p><p><strong>VIN:</strong> <?=h($r['vin'])?></p><p><strong>Color:</strong> <?=h($r['color'])?></p></div></div><div class="box"><h3>Rental Details</h3><table><tr><th>Start</th><th>End</th><th>Pickup</th><th>Dropoff</th><th>Cost</th><th>Deposit</th></tr><tr><td><?= h(cr_date($r['start_date'])) ?></td><td><?= h(cr_date($r['end_date'])) ?></td><td><?=h($r['pickup_location'])?></td><td><?=h($r['dropoff_location'])?></td><td><?=money((float)$r['total_cost'])?></td><td><?=money((float)$r['deposit_amount'])?></td></tr></table></div><div class="box"><h3>Terms</h3><ol><li>The customer must return the vehicle on or before the agreed drop-off date.</li><li>Late return, traffic penalties, fuel shortages, and damage costs are charged to the customer.</li><li>The customer must present valid ID/passport and driving license before vehicle handover.</li><li>The office may record damage reports, payment history, and return confirmation in the system.</li></ol></div><div class="sign"><div class="line">Customer Signature</div><div class="line">Company Representative</div></div></div></body></html>
